    /**
     * Method to retrieve the Item via ItemFetchOneSummary
     * @param 	summary ItemFetchOneSummary 
     * @return 	ItemFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Item getItem( ItemFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ItemFetchOneSummary arg cannot be null" );
    	
    	Item entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Item
        	// --------------------------------------
        	CompletableFuture<Item> futureEntity = queryGateway.query(new FindItemQuery( new LoadItemFilter( summary.getItemId() ) ), ResponseTypes.instanceOf(Item.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Item with id " + summary.getItemId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


